<details><summary>Click to expand</summary>[python]def is_winning(n: int, s: int) -> bool:
    assert s >= 1
    if n % 5 == 1:
        return True
    elif n % 5 == 2:
        return s > 1
    elif n % 5 == 3:
        return s > 2
    elif n % 5 == 4:
        return True
    elif n % 10 == 5:
        return s > 4
    elif n % 10 == 0:
        assert s <= 9  # nothing is claimed about (n,s) for n % 10 == 0, s > 9
        return False
    else:
        raise Exception


for n in range(1, 1000):
    for s in range(1, n):
        if n % 10 == 0 and s >= 10:
            continue
        current = is_winning(n, s)
        if current is True:
            # verify the position is winning by finding at least one losing position one can reach
            # because the main claim misses some pairs, we claim more strongly
            # we can do this with 1 <= t <= 8
            assert not all(is_winning(n - t, t + 1) for t in range(1, 8))
        if current is False:
            # verify the position is losing by showing
            # all positions reachable from it are winning
            assert all(is_winning(n - t, t + 1) for t in range(1, s + 1))
