I[2] = excenter(C[0],A[0],B[0]);
I[3] = excenter(A[0],B[0],C[0]);
A[1] = (I[1] + reflect(B[0],C[0])*(I[1]))/2;
B[1] = (I[2] + reflect(C[0],A[0])*(I[2]))/2;
C[1] = (I[3] + reflect(A[0],B[0])*(I[3]))/2;
O[1] = circumcenter(A[0],B[1],C[1]);
O[2] = circumcenter(B[0],C[1],A[1]);
O[3] = circumcenter(C[0],A[1],B[1]);
X = reflect(O[2],O[3])*(A[1]);

draw(X--A[0],green);
draw(X--B[0],green);
draw(X--C[0],green);
draw(I[1]--X, gray(0.7));
