draw(circumcircle(A[0],B[1],C[1]),red);
draw(circumcircle(B[0],C[1],A[1]),red);
draw(circumcircle(C[0],A[1],B[1]),red);
draw(A[0]--B[0]--C[0]--cycle);
draw(I[1]--I[2]--I[3]--cycle);

dot(" $A$ ", A[0], N);
