*Solution:* Define  $T \coloneqq AF \cap XB$  and  $Q$  to be the second intersection of  $\odot(ABD)$  and  $\odot(AEC)$ . Observe that  $\triangle PED \sim \triangle ABC$ .  
[asy]
import geometry;
import olympiad;
defaultpen(fontsize(11pt));
size(250);
pair A = dir(105);
pair B = dir(210);
pair C = dir(330);
pair F = foot(A,B,C);
pair P = F + 0.34*(A-F);
pair D = extension(C-A+P,P,B,C);
//parallel lines! with vectors ahhh;
pair E = extension(B-A+P, P, B,C);
pair T = 2*F-A;
pair X = intersectionpoints(line(T,B), circumcircle(B,D,A))[0];
pair Y = intersectionpoints(line(T,C), circumcircle(E,C,A))[1];
pair Q = intersectionpoints(circumcircle(A,D,B), circumcircle(A,E,C))[1];
